<?php $terms = sd_homepage_interests(); if ( empty( $terms ) ) { return; } ?><section class="sd-home-section sd-home-interests"><div class="sd-container"><?php sd_homepage_heading( __( 'Explore', 'social-discovery' ), sd_homepage_get( 'sd_home_interests_heading' ), __( 'Browse public topics from the site’s existing content.', 'social-discovery' ) ); ?><div class="sd-home-interest-list sd-home-interest-<?php echo esc_attr( sd_homepage_get( 'sd_home_interests_layout' ) ); ?>"><?php foreach ( $terms as $term ) : ?><a class="sd-home-interest" href="<?php echo esc_url( get_term_link( $term ) ); ?>"><span><?php echo esc_html( $term->name ); ?></span><small><?php echo esc_html( absint( $term->count ) ); ?></small></a><?php endforeach; ?></div></div></section>
